#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    requires
        // Needed so `a.len() + b.len()` is safe and cannot overflow `usize`
        a.len() + b.len() <= usize::MAX,
    ensures
        // Length is the sum of the lengths
        res.len() == a.len() + b.len(),
        // Elements from `a` appear first
        forall|i: int| 0 <= i && i < a.len() ==> res[i] == a[i],
        // Then elements from `b`
        forall|i: int| 0 <= i && i < b.len() ==> res[a.len() + i] == b[i],
{
    let mut res = Vec::with_capacity(a.len() + b.len());
    res.extend_from_slice(a);
    res.extend_from_slice(b);

    // Help the verifier connect the library behavior to our postconditions.
    // (These are redundant if the library specs are strong enough, but safe to keep.)
    assert(res.len() == a.len() + b.len());
    assert(forall|i: int| 0 <= i && i < a.len() ==> res[i] == a[i]);
    assert(forall|i: int| 0 <= i && i < b.len() ==> res[a.len() + i] == b[i]);

    res
}

} // verus!